/* Painted dungeon-leader cards (generated by tools/make_bosscards.py from assets/bosscards/): the whole card for
   the arrival splash, and a square crop of the face for the boss card and info pane portraits. */
const BOSSART = {"rattlefang":{"face":"data:image/webp;base64,"},"beastmaster":{"face":"data:image/webp;base64,"},"ironshell":{"face":"data:image/webp;base64,"},"bonewarden":{"face":"data:image/webp;base64,"},"grakk":{"face":"data:image/webp;base64,"},"cavewyrm":{"face":"data:image/webp;base64,"},"tunnelking":{"face":"data:image/webp;base64,"},"silkweb":{"face":"data:image/webp;base64,"},"mirrorwitch":{"face":"data:image/webp;base64,"},"brakka":{"face":"data:image/webp;base64,"},"tuskmother":{"face":"data:image/webp;base64,"},"cinderlord":{"face":"data:image/webp;base64,"},"nightwing":{"face":"data:image/webp;base64,"},"abbess":{"face":"data:image/webp;base64,"},"arachnara":{"face":"data:image/webp;base64,"},"varn":{"face":"data:image/webp;base64,"},"voltaris":{"face":"data:image/webp;base64,"},"gravelmaw":{"face":"data:image/webp;base64,"},"frostfang":{"face":"data:image/webp;base64,"},"kragmor":{"face":"data:image/webp;base64,"},"vorrith":{"face":"data:image/webp;base64,"},"sandmaw":{"face":"data:image/webp;base64,"},"rotfather":{"face":"data:image/webp;base64,"},"gorr":{"face":"data:image/webp;base64,"},"ossyra":{"face":"data:image/webp;base64,"},"morbus":{"face":"data:image/webp;base64,"},"mire":{"face":"data:image/webp;base64,"},"keening":{"face":"data:image/webp;base64,"},"greyghost":{"face":"data:image/webp;base64,"},"malgrath":{"face":"data:image/webp;base64,"},"abyss":{"face":"data:image/webp;base64,"},"colossus":{"face":"data:image/webp;base64,"},"lich":{"face":"data:image/webp;base64,"},"ogre":{"face":"data:image/webp;base64,"},"titan":{"face":"data:image/webp;base64,"},"voidwyrm":{"face":"data:image/webp;base64,"}};
const BOSS_IMG = {};
for (const k in BOSSART) { const o = BOSS_IMG[k] = {}; for (const s of ['face']) { const im = new Image(); im.onload = () => { o[s] = im; }; im.src = BOSSART[k][s]; } }
